import{_ as a,o as r,c as e,ag as d}from"./chunks/framework.BjY7aUvS.js";const g=JSON.parse('{"title":"个税退税与专项附加扣除 · 家庭该抵的税","description":"个税年度汇算退税指南：每年 3-6 月办理、七项专项附加扣除（子女教育/赡养老人直接抵税）、常见漏退与退税季防骗。","frontmatter":{"title":"个税退税与专项附加扣除 · 家庭该抵的税","issuer":"国家税务总局","source_tier":"一级来源","version":"—","published":"—","source_url":"https://etax.chinatax.gov.cn/","status":"现行服务","tags":["官方查询","个税","退税","专项附加扣除","家庭财务"],"type":"查询页","reviewed":false,"description":"个税年度汇算退税指南：每年 3-6 月办理、七项专项附加扣除（子女教育/赡养老人直接抵税）、常见漏退与退税季防骗。"},"headers":[],"relativePath":"query/tax-refund.md","filePath":"query/tax-refund.md"}'),o={name:"query/tax-refund.md"};function n(s,t,l,h,i,u){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="个税退税与专项附加扣除-·-家庭该抵的税" tabindex="-1">个税退税与专项附加扣除 · 家庭该抵的税 <a class="header-anchor" href="#个税退税与专项附加扣除-·-家庭该抵的税" aria-label="Permalink to &quot;个税退税与专项附加扣除 · 家庭该抵的税&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 会话信息整理；扣除金额标准与办理细则以国家税务总局发布及个税 APP 内指引为准。</p></div><blockquote><p><strong>官方入口</strong>：<strong>个人所得税 APP</strong>（国家税务总局，官方应用商店）；<a href="https://etax.chinatax.gov.cn/" target="_blank" rel="noreferrer">自然人电子税务局</a>（已核验域名，站点较慢）；热线 12366。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><ul><li><strong>年度汇算</strong>：每年 <strong>3 月 1 日～6 月 30 日</strong>，对上一年度综合所得&quot;多退少补&quot;——退税是家庭年度现金流事件，<strong>不办=自动放弃</strong>。</li><li><strong>专项附加扣除</strong>是合法少缴税的开关：七项——子女教育、继续教育、大病医疗、住房贷款利息、住房租金、<strong>赡养老人</strong>、3 岁以下婴幼儿照护（待核验）。</li><li>对本站受众的直接意义：<strong>孩子上学、赡养父母</strong>两项，正是大多数家庭能用上的抵税项。</li></ul><h2 id="行动清单-退税季前做完" tabindex="-1">行动清单（退税季前做完） <a class="header-anchor" href="#行动清单-退税季前做完" aria-label="Permalink to &quot;行动清单（退税季前做完）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>下载<strong>个人所得税 APP</strong> 注册实名，核对受雇信息（多一家&quot;任职受雇&quot;= 身份被冒用，立即申诉）</td><td>个税 APP</td></tr><tr><td>逐项填全<strong>七项专项附加扣除</strong>：子女教育按孩、赡养老人分摊方式与兄弟姐妹约定好（分摊一旦选定年度内不变，待核验）、房贷利息与租金<strong>二选一</strong></td><td>个税 APP 内指引</td></tr><tr><td>汇算时试算<strong>年终奖计税方式</strong>（单独计税/并入综合所得两种都点一下，哪种退税多选哪种）</td><td>APP 汇算向导</td></tr><tr><td>填本人<strong>银行卡</strong>（Ⅰ类户），退税直达卡</td><td>个税 APP</td></tr></tbody></table><h2 id="常见漏退与驳回" tabindex="-1">常见漏退与驳回 <a class="header-anchor" href="#常见漏退与驳回" aria-label="Permalink to &quot;常见漏退与驳回&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情形</th><th>说明</th></tr></thead><tbody><tr><td>漏填专项附加扣除</td><td>最常见的&quot;少退税&quot;原因——尤其赡养老人、房租</td></tr><tr><td>有兼职/劳务报酬</td><td>预缴率不同，汇算常能退回一部分</td></tr><tr><td>银行卡信息有误</td><td>退税失败退回，改卡重新发起</td></tr><tr><td>单位帮办的没选年终奖方式</td><td>汇算时本人可重新选择</td></tr></tbody></table><h2 id="退税季防骗-每年准时上线" tabindex="-1">退税季防骗（每年准时上线） <a class="header-anchor" href="#退税季防骗-每年准时上线" aria-label="Permalink to &quot;退税季防骗（每年准时上线）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方事实</th></tr></thead><tbody><tr><td>&quot;您有一笔 2025 年退税待领取，点链接办理&quot;</td><td>官方<strong>只通过个人所得税 APP/自然人电子税务局</strong>办理，从不发链接、不要验证码</td></tr><tr><td>&quot;专业退税代办，手续费 30%&quot;</td><td>汇算在 APP 里<strong>几分钟自己就能点完</strong>，且虚假填报骗税属违法</td></tr><tr><td>【本站提示】收到&quot;税务稽查&quot;电话要转账的，直接挂断打 12366 核实</td><td>—</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>家庭账本：<a href="/SageRelay/data/minimum-wage-2026.html">最低工资</a> · <a href="/SageRelay/social/pension-after-death.html">养老金身故权益</a> · <a href="/SageRelay/query/skill-subsidy.html">技能补贴</a></li><li>被欠薪：<a href="/SageRelay/query/labor-rights.html">劳动维权</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>主管</td><td>国家税务总局（个人所得税 APP / 自然人电子税务局 / 12366）</td></tr><tr><td>政策</td><td>个人所得税法专项附加扣除规定及国务院提高三项扣除标准的决定（待核验）</td></tr></tbody></table>',15)])])}const b=a(o,[["render",n]]);export{g as __pageData,b as default};
